export type Post = {
  id: number
  title: string
  body: string
}

export type Comment = {
  id: number
  name: string
  body: string
  email: string
}

const baseUrl = 'https://jsonplaceholder.typicode.com'

export async function getPosts(revalidate: number): Promise<Post[]> {
  const response = await fetch(`${baseUrl}/posts`, { next: { revalidate } })
  if (!response.ok) throw new Error('Failed to load posts')
  return (await response.json()) as Post[]
}

export async function getPost(id: string): Promise<Post | null> {
  const response = await fetch(`${baseUrl}/posts/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })
  if (response.status === 404) return null
  if (!response.ok) throw new Error('Failed to load post')
  const post = (await response.json()) as Post
  return post.id && typeof post.title === 'string' ? post : null
}

export async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch(`${baseUrl}/posts/${encodeURIComponent(id)}/comments`, {
    next: { revalidate: 300 },
  })
  if (!response.ok) throw new Error('Failed to load comments')
  return (await response.json()) as Comment[]
}

